const requiredWebhookSecret = String($env.N8N_WEBHOOK_SHARED_SECRET || '');
if (requiredWebhookSecret) {
  const requestHeaders = ($json && $json.headers) || {};
  const providedWebhookSecret = String(requestHeaders['x-rag-webhook-secret'] || requestHeaders['X-RAG-Webhook-Secret'] || '');
  if (providedWebhookSecret !== requiredWebhookSecret) throw new Error('Unauthorized webhook request');
}
// Runtime service URLs: environment override with Compose fallback.
const runtimeTraceEmitterUrl = $env.TRACE_EMITTER_URL || 'http://trace-emitter:8001/v1/traces';
const input = $json.body || $json || {};
const eventKind = String(input.event_kind || '');
const feedbackType = String(input.feedback_type || '');
const feedbackValue = String(input.feedback_value || '');
const reactionName = String(input.reaction_name || '');
const messageId = String(input.discord_response_message_id || '');
const authorHash = String(input.feedback_author_id_hash || '').toLowerCase();
const guildId = String(input.discord_guild_id || input.guild_id || '');
const channelId = String(input.channel_id || '');
const canonicalReactionName = reactionName.replace(/\uFE0F/g, '').replace(/[\u{1F3FB}-\u{1F3FF}]/gu, '');
const expected = { [String.fromCodePoint(0x1F44D)]: ['positive', 'thumbs_up'], [String.fromCodePoint(0x1F44E)]: ['negative', 'thumbs_down'] };
if (!['reaction_added', 'reaction_removed'].includes(eventKind)) throw new Error('Unsupported feedback event_kind');
if (!expected[canonicalReactionName] || expected[canonicalReactionName][0] !== feedbackType || expected[canonicalReactionName][1] !== feedbackValue) throw new Error('Reaction normalization mismatch');
if (!/^\d+$/.test(messageId)) throw new Error('discord_response_message_id must be a Discord snowflake');
if (!/^[a-f0-9]{64}$/.test(authorHash)) throw new Error('feedback_author_id_hash must be a SHA-256 hex digest');
if (!/^\d+$/.test(guildId)) throw new Error('guild_id must be a Discord snowflake');
if (!/^\d+$/.test(channelId)) throw new Error('channel_id must be a Discord snowflake');
const discordResponseLink = 'https://discord.com/channels/' + guildId + '/' + channelId + '/' + messageId;
return [{ json: {
  event_kind: eventKind,
  operation: eventKind === 'reaction_added' ? 'add' : 'remove',
  feedback_source: 'reaction',
  discord_response_message_id: messageId,
  discord_guild_id: guildId,
  channel_id: channelId,
  discord_response_link: discordResponseLink,
  workflow_contract_version: 'phase-10-feedback-v2',
  feedback_author_id_hash: authorHash,
  feedback_type: feedbackType,
  feedback_value: feedbackValue,
  reaction_name: reactionName,
  review_candidate: eventKind === 'reaction_added' && feedbackType === 'negative',
  phoenix_collector_url: runtimeTraceEmitterUrl,
  occurred_at: String(input.occurred_at || new Date().toISOString())
} }];

// Runtime service URLs: environment override with Compose fallback.
const runtimeTraceEmitterUrl = $env.TRACE_EMITTER_URL || 'http://trace-emitter:8001/v1/traces';
const result = $json || {};
const nowNs = String(Date.now() * 1000000);
const seed = String(result.discord_response_message_id || '').padStart(32, '0').slice(-32);
const hexToBase64 = (hex) => { let value = ''; for (let i = 0; i < hex.length; i += 2) value += String.fromCharCode(parseInt(hex.slice(i, i + 2), 16)); return btoa(value); };
const attrs = (values) => Object.entries(values).map(([key, value]) => ({ key, value: typeof value === 'boolean' ? { boolValue: value } : { stringValue: String(value ?? '') } }));
const eventName = result.matched ? 'feedback.linked' : 'feedback.unmatched';
const payload = { resourceSpans: [{ resource: { attributes: attrs({ 'service.name': 'discord-rag-bot', 'phoenix.project.name': 'discord-rag-bot-phase-10' }) }, scopeSpans: [{ scope: { name: 'n8n.phase10.feedback', version: '1.0.0' }, spans: [{ traceId: hexToBase64(seed), spanId: hexToBase64(seed.slice(0, 16)), name: eventName, kind: 1, startTimeUnixNano: nowNs, endTimeUnixNano: nowNs, attributes: attrs({ transaction_id: result.transaction_id, discord_response_message_id: result.discord_response_message_id, discord_response_link: result.discord_response_link, workflow_contract_version: result.workflow_contract_version, feedback_type: result.feedback_type, persistence_operation: result.persistence_operation, review_candidate: result.review_candidate, matched: result.matched }), status: { code: 1 } }] }] }] };
return [{ json: { ...result, event_name: eventName, phoenix_collector_url: runtimeTraceEmitterUrl, phoenix_trace_payload: payload } }];
